mods.body:
body {
  background: #f5f2eb !important;
  margin: 0 !important;
  padding: 18px 12px 48px !important;
}
#hnmain {
  width: min(860px, 100%) !important;
  background: #faf8f5 !important;
  border: 1px solid rgba(28, 25, 23, 0.12) !important;
  border-radius: 10px !important;
  overflow: hidden !important;
}
.titleline a,
.commtext {
  font-size: 15px !important;
  line-height: 1.65 !important;
}

#abs-outer,
#content {
  max-width: 820px !important;
  margin: 0 auto !important;
  padding: 20px !important;
}
h1.title {
  font-size: 1.65rem !important;
  line-height: 1.3 !important;
  margin-bottom: 12px !important;
}
blockquote.abstract {
  font-size: 16px !important;
  line-height: 1.78 !important;
  color: #1c1917 !important;
}

(() => {
  const titleEl = document.querySelector('h1.title');
  if (!titleEl || document.getElementById('pc-arxiv-cite-btn')) return;
  const btn = document.createElement('button');
  btn.id = 'pc-arxiv-cite-btn';
  btn.type = 'button';
  btn.textContent = 'Copy Citation';
  btn.style.cssText = 'display:inline-flex;align-items:center;gap:6px;margin:0 0 10px;padding:5px 11px;border-radius:7px;border:1px solid #C95533;background:#FAF8F5;color:#9A3412;font:600 12px/1.3 system-ui,sans-serif;cursor:pointer';
  btn.addEventListener('click', () => {
    const cleanTitle = titleEl.textContent.replace(/^Title:\s*/i, '').replace(/\s+/g, ' ').trim();
    const md = `[${cleanTitle}](${location.href})`;
    navigator.clipboard.writeText(md).then(() => {
      const prev = btn.textContent;
      btn.textContent = 'Copied ✓';
      setTimeout(() => { btn.textContent = prev; }, 1400);
    }).catch(() => {});
  });
  titleEl.parentNode.insertBefore(btn, titleEl);
})();

